rue\n    rules:\n      - type: pattern\n        pattern: CORTEX_SENSE_DEMO.GAME_SALES.SV_GAME_SALES\n        user_prompt: \"GAME_SALES-only revenue model: digital, hardware and subscription revenue; digital revenue by title and by PlayStation title code; revenue by monetization type; total spend per customer\"\n\n  - name: stage_files\n    type: snowflake_content\n    enabled: true\n    rules:\n      # Mirrors the local stage_files/ folder; re-upload after editing:\n      #   snow sql -c CORTEX_SENSE_DEMO_CONN --enable-templating NONE -f install/06-upload-knowledge-base.sql\n      - type: file\n        stage: CORTEX_SENSE_DEMO.CONTEXTS.KNOWLEDGE_BASE\n        file_pattern: \"\"\n        user_prompt: \"gaming knowledge base — internal FY2027 portfolio strategy memo (franchise core/growth/harvest tiers, strategic priorities) and EU loot box regulatory brief (EU risk tiers HIGH/ELEVATED/WATCH/LOW for live-service monetization, required mitigations, and how to assess EU risk)\"\n\n# All business rules stored as feedback records via record-feedback.\n# See list-feedback for the active definitions, retrieval steers, and procedural rules.\n", "overwrite": true}}$$) AS result;

